CREATE TABLE user_rank (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "rank_id"  bigint NOT NULL,
    "user_id"  bigint NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz,
    CONSTRAINT "user_rank_discipline_user_id_fkey"
        FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "user_rank_discipline_rank_id_fkey"
        FOREIGN KEY ("rank_id") REFERENCES "rank" ("id") DEFERRABLE INITIALLY IMMEDIATE
);